SourceCode.Declaration:
/// <summary>
/// The TFMCategoryAttribute class is an attribute to register with your classes or methods, that describes which category they belong to
/// </summary>
public class TFMCategoryAttribute extends SysAttribute implements SysExtensionIAttribute
{
    TFMCategoryName        category;
    HelpTxt                helpText;

}

Method.Source:
void new(TFMCategoryName _category, HelpTxt _helpText = '')
{
    super();

    category = _category;
    helpText = _helpText;

}

///<summary>
/// Returns the key used for storing cached data for this attribute.
/// </summary>
/// <returns>
/// A string representing the cache key.
/// </returns>
public str parmCacheKey()
{
    return classStr(TFMCategoryAttribute)+';'+category+helpText;
}

public TFMCategoryName parmCategory(TFMCategoryName _category = category)
{
    category = _category;
    return category;
}

/// <summary>
/// Help text of the control to let the user know what the control does.
/// </summary>
public HelpTxt parmHelpText(HelpTxt _helpText = helpText)
{
    helpText = _helpText;
    return helpText;
}

///<summary>
/// Determines if the same instance should be returned by the extension framework.
/// </summary>
/// <returns>
/// true if the same instance should be returned; otherwise false.
/// </returns>
public boolean useSingleton()
{
    return false;
}
